class Course {
  constructor(name, hours) {
    this.name = name;
    this.hours = hours;
  }

  describe() {
    return this.name + ' · ' + this.hours + '시간';
  }
}

class Workshop extends Course {
  constructor(name, hours, seats) {
    super(name, hours);
    this.seats = seats;
  }

  describe() {
    return super.describe() + ' · 정원 ' + this.seats + '명';
  }
}

class Bundle {
  constructor(items) {
    this.items = items;
  }

  describe() {
    return this.items.map((item) => item.describe()).join(' + ');
  }
}

// 이 함수는 그대로 두세요
function report() {
  const a = new Course('리액트 입문', 8);
  const w = new Workshop('리액트 심화', 4, 12);
  const bundle = new Bundle([a, w]);
  return bundle.describe()
    + ' / Workshop 은 Course 인가: ' + (w instanceof Course)
    + ' / Bundle 은 Course 인가: ' + (bundle instanceof Course);
}
